-- Phoenix Banner Image Asset Handler
-- Supports: Direct Asset ID, executor getcustomasset / writefile, or fallback thumbnail
local PHOENIX_DECAL_ASSET_ID = "" -- Optional: If you upload the decal to Roblox, enter its ID or rbxassetid:// here

local PHOENIX_IMAGE_B64 = ""

local function getPhoenixImage()
    if PHOENIX_DECAL_ASSET_ID ~= "" then
        if string.find(PHOENIX_DECAL_ASSET_ID, "://") then
            return PHOENIX_DECAL_ASSET_ID
        else
            return "rbxassetid://" .. PHOENIX_DECAL_ASSET_ID
        end
    end

    local getAsset = getcustomasset or getsynasset
    if getAsset and writefile then
        local filename = "RideAPet_Phoenix.jpg"
        local success = pcall(function()
            if not isfile or not isfile(filename) then
                local b64Decode = (crypt and crypt.base64decode) or (base64_decode)
                local rawBytes
                if b64Decode then
                    rawBytes = b64Decode(PHOENIX_IMAGE_B64)
                else
                    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
                    local t = {}
                    for i = 1, 64 do t[b:sub(i, i)] = i - 1 end
                    local out = {}
                    local len = #PHOENIX_IMAGE_B64
                    local pad = (PHOENIX_IMAGE_B64:sub(-2) == '==' and 2) or (PHOENIX_IMAGE_B64:sub(-1) == '=' and 1) or 0
                    for i = 1, len - pad, 4 do
                        local a = t[PHOENIX_IMAGE_B64:sub(i, i)] or 0
                        local b_ = t[PHOENIX_IMAGE_B64:sub(i + 1, i + 1)] or 0
                        local c = t[PHOENIX_IMAGE_B64:sub(i + 2, i + 2)] or 0
                        local d = t[PHOENIX_IMAGE_B64:sub(i + 3, i + 3)] or 0
                        local n = (a * 262144) + (b_ * 4096) + (c * 64) + d
                        table.insert(out, string.char(math.floor(n / 65536) % 256))
                        if i + 2 <= len - pad then table.insert(out, string.char(math.floor(n / 256) % 256)) end
                        if i + 3 <= len - pad then table.insert(out, string.char(n % 256)) end
                    end
                    rawBytes = table.concat(out)
                end
                writefile(filename, rawBytes)
            end
        end)
        if success then
            local asset = getAsset(filename)
            if asset then return asset end
        end
    end

    return "rbxthumb://type=GameThumbnail&id=10035204815&w=768&h=432"
end

