-- Helper: Create Modern Toggle Row
local function addToggle(container, text, defaultState, callback)
    local row = Instance.new("Frame")
    row.Parent = container
    row.BackgroundTransparency = 1.000
    row.Size = UDim2.new(1, 0, 0, 28)

    local label = Instance.new("TextLabel")
    label.Parent = row
    label.BackgroundTransparency = 1.000
    label.Position = UDim2.new(0, 0, 0, 0)
    label.Size = UDim2.new(1, -70, 1, 0)
    label.Font = Enum.Font.Gotham
    label.Text = text
    label.TextColor3 = Color3.fromRGB(225, 228, 235)
    label.TextSize = 11.000
    label.TextXAlignment = Enum.TextXAlignment.Left

    local btn = Instance.new("TextButton")
    btn.Parent = row
    btn.BorderSizePixel = 0
    btn.Position = UDim2.new(1, -64, 0.5, -12)
    btn.Size = UDim2.new(0, 64, 0, 24)
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 11.000

    local btnCorner = Instance.new("UICorner")
    btnCorner.CornerRadius = UDim.new(0, 5)
    btnCorner.Parent = btn

    local btnStroke = Instance.new("UIStroke")
    btnStroke.Thickness = 1
    btnStroke.Parent = btn

    local state = defaultState or false
    local function updateVisual()
        if state then
            btn.BackgroundColor3 = Color3.fromRGB(32, 95, 60)
            btn.TextColor3 = Color3.fromRGB(255, 255, 255)
            btnStroke.Color = Color3.fromRGB(48, 140, 88)
            btn.Text = "ON"
        else
            btn.BackgroundColor3 = Color3.fromRGB(30, 32, 38)
            btn.TextColor3 = Color3.fromRGB(155, 160, 170)
            btnStroke.Color = Color3.fromRGB(50, 54, 64)
            btn.Text = "OFF"
        end
    end
    updateVisual()

    btn.MouseEnter:Connect(function()
        if not state then
            btn.BackgroundColor3 = Color3.fromRGB(36, 38, 46)
        end
    end)
    btn.MouseLeave:Connect(function()
        if not state then
            btn.BackgroundColor3 = Color3.fromRGB(30, 32, 38)
        end
    end)

    btn.MouseButton1Click:Connect(function()
        if clickSound then clickSound:Play() end
        state = not state
        updateVisual()
        if callback then callback(state) end
    end)

    return row
end

