-- Helper: Create Modern Slider Row
local function addSlider(container, text, min, max, defaultVal, callback)
    local row = Instance.new("Frame")
    row.Parent = container
    row.BackgroundTransparency = 1.000
    row.Size = UDim2.new(1, 0, 0, 36)

    local label = Instance.new("TextLabel")
    label.Parent = row
    label.BackgroundTransparency = 1.000
    label.Position = UDim2.new(0, 0, 0, 0)
    label.Size = UDim2.new(1, -60, 0, 16)
    label.Font = Enum.Font.Gotham
    label.Text = text
    label.TextColor3 = Color3.fromRGB(225, 228, 235)
    label.TextSize = 11.000
    label.TextXAlignment = Enum.TextXAlignment.Left

    local valLabel = Instance.new("TextLabel")
    valLabel.Parent = row
    valLabel.BackgroundTransparency = 1.000
    valLabel.Position = UDim2.new(1, -60, 0, 0)
    valLabel.Size = UDim2.new(0, 60, 0, 16)
    valLabel.Font = Enum.Font.GothamBold
    valLabel.Text = tostring(defaultVal)
    valLabel.TextColor3 = Color3.fromRGB(160, 180, 215)
    valLabel.TextSize = 11.000
    valLabel.TextXAlignment = Enum.TextXAlignment.Right

    local track = Instance.new("Frame")
    track.Parent = row
    track.BackgroundColor3 = Color3.fromRGB(30, 32, 38)
    track.BorderSizePixel = 0
    track.Position = UDim2.new(0, 0, 0, 20)
    track.Size = UDim2.new(1, 0, 0, 8)

    local trackCorner = Instance.new("UICorner")
    trackCorner.CornerRadius = UDim.new(0, 4)
    trackCorner.Parent = track

    local trackStroke = Instance.new("UIStroke")
    trackStroke.Color = Color3.fromRGB(50, 54, 64)
    trackStroke.Thickness = 1
    trackStroke.Parent = track

    local defaultPct = math.clamp((defaultVal - min) / (max - min), 0, 1)

    local fill = Instance.new("Frame")
    fill.Parent = track
    fill.BackgroundColor3 = Color3.fromRGB(52, 92, 148)
    fill.BorderSizePixel = 0
    fill.Size = UDim2.new(defaultPct, 0, 1, 0)

    local fillCorner = Instance.new("UICorner")
    fillCorner.CornerRadius = UDim.new(0, 4)
    fillCorner.Parent = fill

    local handle = Instance.new("Frame")
    handle.Parent = track
    handle.AnchorPoint = Vector2.new(0.5, 0.5)
    handle.Position = UDim2.new(defaultPct, 0, 0.5, 0)
    handle.Size = UDim2.new(0, 14, 0, 14)
    handle.BackgroundColor3 = Color3.fromRGB(220, 225, 235)
    handle.BorderSizePixel = 0

    local handleCorner = Instance.new("UICorner")
    handleCorner.CornerRadius = UDim.new(0, 7)
    handleCorner.Parent = handle

    local handleStroke = Instance.new("UIStroke")
    handleStroke.Color = Color3.fromRGB(60, 70, 85)
    handleStroke.Thickness = 1
    handleStroke.Parent = handle

    local hitbox = Instance.new("TextButton")
    hitbox.Parent = row
    hitbox.BackgroundTransparency = 1.000
    hitbox.Text = ""
    hitbox.Position = UDim2.new(0, -4, 0, 14)
    hitbox.Size = UDim2.new(1, 8, 0, 20)

    local isSliding = false

    local function setValue(rawVal)
        local val = math.clamp(math.floor(rawVal + 0.5), min, max)
        local pct = math.clamp((val - min) / (max - min), 0, 1)
        fill.Size = UDim2.new(pct, 0, 1, 0)
        handle.Position = UDim2.new(pct, 0, 0.5, 0)
        valLabel.Text = tostring(val)
        if callback then callback(val) end
    end

    local function updateFromInput(input)
        local trackPos = track.AbsolutePosition.X
        local trackWidth = track.AbsoluteSize.X
        if trackWidth <= 0 then return end
        local pct = math.clamp((input.Position.X - trackPos) / trackWidth, 0, 1)
        local val = min + (max - min) * pct
        setValue(val)
    end

    hitbox.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            isSliding = true
            updateFromInput(input)
            local conn
            conn = input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    isSliding = false
                    if conn then conn:Disconnect() end
                end
            end)
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if isSliding and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            updateFromInput(input)
        end
    end)

    return row, setValue
end

-- Helper: Create Modern Dropdown Row (Supports Single & Multi-Select)
local function addDropdown(container, text, options, defaultChoice, callback, isMulti)
    local selected = {}
    if isMulti then
        if type(defaultChoice) == "table" then
            for k, v in pairs(defaultChoice) do
                if type(k) == "string" and v == true then
                    selected[k] = true
                elseif type(v) == "string" then
                    selected[v] = true
                end
            end
        elseif defaultChoice then
            selected[defaultChoice] = true
        else
            selected["All"] = true
        end
    else
        selected = defaultChoice or options[1]
    end

    local isOpen = false

    local function getDisplayText()
        if not isMulti then
            return tostring(selected)
        end
        if selected["All"] then
            return "All"
        end
        local list = {}
        for _, opt in ipairs(options) do
            if opt ~= "All" and selected[opt] then
                table.insert(list, opt)
            end
        end
        if #list == 0 then
            return "None"
        elseif #list == 1 then
            return list[1]
        elseif #list == 2 then
            return list[1] .. ", " .. list[2]
        else
            return list[1] .. " (+" .. tostring(#list - 1) .. ")"
        end
    end

    local row = Instance.new("Frame")
    row.Parent = container
    row.BackgroundTransparency = 1.000
    row.Size = UDim2.new(1, 0, 0, 28)
    row.ClipsDescendants = true

    local headerFrame = Instance.new("Frame")
    headerFrame.Parent = row
    headerFrame.BackgroundTransparency = 1.000
    headerFrame.Size = UDim2.new(1, 0, 0, 28)

    local label = Instance.new("TextLabel")
    label.Parent = headerFrame
    label.BackgroundTransparency = 1.000
    label.Position = UDim2.new(0, 0, 0, 0)
    label.Size = UDim2.new(1, -165, 1, 0)
    label.Font = Enum.Font.Gotham
    label.Text = text
    label.TextColor3 = Color3.fromRGB(225, 228, 235)
    label.TextSize = 11.000
    label.TextXAlignment = Enum.TextXAlignment.Left

    local mainBtn = Instance.new("TextButton")
    mainBtn.Parent = headerFrame
    mainBtn.BackgroundColor3 = Color3.fromRGB(32, 36, 46)
    mainBtn.BorderSizePixel = 0
    mainBtn.Position = UDim2.new(1, -160, 0.5, -12)
    mainBtn.Size = UDim2.new(0, 160, 0, 24)
    mainBtn.Font = Enum.Font.GothamMedium
    mainBtn.Text = "  " .. getDisplayText() .. "  ▾"
    mainBtn.TextColor3 = Color3.fromRGB(230, 235, 245)
    mainBtn.TextSize = 10.000
    mainBtn.TextXAlignment = Enum.TextXAlignment.Left
    mainBtn.TextTruncate = Enum.TextTruncate.AtEnd

    local btnCorner = Instance.new("UICorner")
    btnCorner.CornerRadius = UDim.new(0, 5)
    btnCorner.Parent = mainBtn

    local btnStroke = Instance.new("UIStroke")
    btnStroke.Color = Color3.fromRGB(55, 60, 72)
    btnStroke.Thickness = 1
    btnStroke.Parent = mainBtn

    local listFrame = Instance.new("ScrollingFrame")
    listFrame.Parent = row
    listFrame.BackgroundColor3 = Color3.fromRGB(18, 20, 26)
    listFrame.BorderSizePixel = 0
    listFrame.Position = UDim2.new(0, 0, 0, 32)
    listFrame.Size = UDim2.new(1, 0, 0, 130)
    listFrame.ScrollBarThickness = 3
    listFrame.ScrollBarImageColor3 = Color3.fromRGB(70, 75, 90)
    listFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
    listFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
    listFrame.Visible = false

    local listCorner = Instance.new("UICorner")
    listCorner.CornerRadius = UDim.new(0, 5)
    listCorner.Parent = listFrame

    local listStroke = Instance.new("UIStroke")
    listStroke.Color = Color3.fromRGB(48, 52, 64)
    listStroke.Thickness = 1
    listStroke.Parent = listFrame

    local listLayout = Instance.new("UIListLayout")
    listLayout.Parent = listFrame
    listLayout.SortOrder = Enum.SortOrder.LayoutOrder
    listLayout.Padding = UDim.new(0, 2)

    local listPad = Instance.new("UIPadding")
    listPad.Parent = listFrame
    listPad.PaddingTop = UDim.new(0, 4)
    listPad.PaddingBottom = UDim.new(0, 4)
    listPad.PaddingLeft = UDim.new(0, 4)
    listPad.PaddingRight = UDim.new(0, 4)

    local optionBtns = {}

    local function updateVisuals()
        mainBtn.Text = "  " .. getDisplayText() .. (isOpen and "  ▴" or "  ▾")
        for opt, b in pairs(optionBtns) do
            local isSel = false
            if isMulti then
                isSel = selected[opt] == true
                b.Text = isSel and ("  ✓  " .. tostring(opt)) or ("      " .. tostring(opt))
            else
                isSel = (selected == opt)
                b.Text = "  " .. tostring(opt)
            end
            b.BackgroundColor3 = isSel and Color3.fromRGB(38, 50, 72) or Color3.fromRGB(24, 26, 34)
            b.TextColor3 = isSel and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(180, 185, 195)
        end
    end

    local function toggleDropdown()
        isOpen = not isOpen
        if isOpen then
            row.Size = UDim2.new(1, 0, 0, 168)
            listFrame.Visible = true
            btnStroke.Color = Color3.fromRGB(75, 110, 170)
        else
            row.Size = UDim2.new(1, 0, 0, 28)
            listFrame.Visible = false
            btnStroke.Color = Color3.fromRGB(55, 60, 72)
        end
        updateVisuals()
    end

    mainBtn.MouseButton1Click:Connect(function()
        if clickSound then clickSound:Play() end
        toggleDropdown()
    end)

    for i, opt in ipairs(options) do
        local optBtn = Instance.new("TextButton")
        optBtn.Parent = listFrame
        optBtn.BackgroundColor3 = Color3.fromRGB(24, 26, 34)
        optBtn.BorderSizePixel = 0
        optBtn.Size = UDim2.new(1, 0, 0, 24)
        optBtn.Font = Enum.Font.Gotham
        optBtn.TextColor3 = Color3.fromRGB(180, 185, 195)
        optBtn.TextSize = 10.000
        optBtn.TextXAlignment = Enum.TextXAlignment.Left
        optBtn.LayoutOrder = i

        local optCorner = Instance.new("UICorner")
        optCorner.CornerRadius = UDim.new(0, 4)
        optCorner.Parent = optBtn

        optBtn.MouseEnter:Connect(function()
            local isSel = isMulti and (selected[opt] == true) or (selected == opt)
            if not isSel then
                optBtn.BackgroundColor3 = Color3.fromRGB(32, 36, 48)
                optBtn.TextColor3 = Color3.fromRGB(230, 235, 245)
            end
        end)
        optBtn.MouseLeave:Connect(function()
            local isSel = isMulti and (selected[opt] == true) or (selected == opt)
            if not isSel then
                optBtn.BackgroundColor3 = Color3.fromRGB(24, 26, 34)
                optBtn.TextColor3 = Color3.fromRGB(180, 185, 195)
            end
        end)

        optBtn.MouseButton1Click:Connect(function()
            if clickSound then clickSound:Play() end
            if isMulti then
                if opt == "All" then
                    selected = { ["All"] = true }
                else
                    selected["All"] = nil
                    if selected[opt] then
                        selected[opt] = nil
                    else
                        selected[opt] = true
                    end
                    local hasAny = false
                    for _, v in pairs(selected) do
                        if v then hasAny = true break end
                    end
                    if not hasAny then
                        selected["All"] = true
                    end
                end
                updateVisuals()
                if callback then callback(selected) end
            else
                selected = opt
                updateVisuals()
                toggleDropdown()
                if callback then callback(selected) end
            end
        end)

        optionBtns[opt] = optBtn
    end

    updateVisuals()
    return row
end

