local function getEggScore(name, rarity)
    local eScore = eggTierRank[name]
    if not eScore and name then
        local lower = string.lower(name)
        for eName, score in pairs(eggTierRank) do
            if string.find(lower, string.lower(string.gsub(eName, " Egg", ""))) then
                eScore = score
                break
            end
        end
    end
    eScore = eScore or 0

    local rScore = rarityTierRank[rarity]
    if not rScore and rarity then
        local lower = string.lower(rarity)
        for rName, score in pairs(rarityTierRank) do
            if string.lower(rName) == lower then
                rScore = score
                break
            end
        end
    end
    rScore = rScore or 0

    return eScore, rScore
end

local function getEggInfo(obj)
    local name = string.lower(obj.Name)
    if string.find(name, "track") or string.find(name, "npc") or string.find(name, "merchant") or string.find(name, "shop") or string.find(name, "vendor") then
        return nil, nil
    end
    for eggKey, rty in pairs(eggRarityMap) do
        local cleanKey = string.gsub(eggKey, "%s+", "")
        if string.find(name, eggKey) or string.find(name, cleanKey) then
            return eggProperNames[eggKey] or eggKey, rty
        end
    end
    for _, attr in ipairs({"Egg", "EggName", "Rarity", "Type"}) do
        local val = obj:GetAttribute(attr)
        if val and type(val) == "string" then
            local valLower = string.lower(val)
            for eggKey, rty in pairs(eggRarityMap) do
                if string.find(valLower, eggKey) or string.find(valLower, string.lower(rty)) then
                    return eggProperNames[eggKey] or eggKey, rty
                end
            end
        end
    end
    for _, child in ipairs(obj:GetDescendants()) do
        if child:IsA("TextLabel") or child:IsA("TextButton") then
            local t = string.lower(child.Text)
            for eggKey, rty in pairs(eggRarityMap) do
                if string.find(t, eggKey) then
                    return eggProperNames[eggKey] or eggKey, rty
                end
            end
        end
    end
    if string.find(name, "egg") and not string.find(name, "track") and not string.find(name, "npc") then
        return obj.Name, "Common"
    end
    return nil, nil
end

local lastKnownPlotCF = nil

local function getPlayerPlotCFrame()
    local pName = string.lower(localPlayer.Name)
    local pDisplayName = string.lower(localPlayer.DisplayName)
    local pUserId = tostring(localPlayer.UserId)

    local function getCFrameFromInstance(inst)
        if inst:IsA("Model") then
            local pp = inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart")
            if pp then return pp.CFrame + Vector3.new(0, 3.5, 0) end
            local p = inst:GetPivot()
            if p then return p + Vector3.new(0, 3.5, 0) end
        elseif inst:IsA("BasePart") then
            return inst.CFrame + Vector3.new(0, 3.5, 0)
        end
        return nil
    end

    -- 1. Check dedicated plot / tycoon / base containers
    local plotContainers = {"Plots", "Bases", "Islands", "Tycoons", "PlayerPlots", "Houses", "Farms", "Nests", "Map"}
    for _, cName in ipairs(plotContainers) do
        local container = workspace:FindFirstChild(cName)
        if container then
            for _, plot in ipairs(container:GetChildren()) do
                local plName = string.lower(plot.Name)
                if string.find(plName, pName) or string.find(plName, pDisplayName) or string.find(plName, pUserId) then
                    local cf = getCFrameFromInstance(plot)
                    if cf then
                        lastKnownPlotCF = cf
                        return cf
                    end
                end

                for _, attr in ipairs({"Owner", "Player", "UserId", "OwnerName", "PlayerName"}) do
                    local val = plot:GetAttribute(attr)
                    if val and (string.lower(tostring(val)) == pName or string.lower(tostring(val)) == pDisplayName or tostring(val) == pUserId) then
                        local cf = getCFrameFromInstance(plot)
                        if cf then
                            lastKnownPlotCF = cf
                            return cf
                        end
                    end
                end

                for _, child in ipairs(plot:GetDescendants()) do
                    if (child:IsA("StringValue") or child:IsA("ObjectValue")) and string.find(string.lower(child.Name), "owner") then
                        if child:IsA("StringValue") and (string.lower(child.Value) == pName or string.lower(child.Value) == pDisplayName) then
                            local cf = getCFrameFromInstance(plot)
                            if cf then
                                lastKnownPlotCF = cf
                                return cf
                            end
                        elseif child:IsA("ObjectValue") and child.Value == localPlayer then
                            local cf = getCFrameFromInstance(plot)
                            if cf then
                                lastKnownPlotCF = cf
                                return cf
                            end
                        end
                    end
                    if child:IsA("TextLabel") or child:IsA("SurfaceGui") then
                        local text = string.lower(child:IsA("TextLabel") and child.Text or "")
                        if (string.find(text, pName) or string.find(text, pDisplayName)) and (string.find(text, "base") or string.find(text, "plot") or string.find(text, "home") or string.find(text, "'s")) then
                            local cf = getCFrameFromInstance(plot)
                            if cf then
                                lastKnownPlotCF = cf
                                return cf
                            end
                        end
                    end
                end
            end
        end
    end

    -- 2. General workspace scan for any plot/base matching player's name
    for _, obj in ipairs(workspace:GetChildren()) do
        if obj ~= localPlayer.Character and (obj:IsA("Model") or obj:IsA("Folder")) then
            local objName = string.lower(obj.Name)
            if (string.find(objName, pName) or string.find(objName, pDisplayName)) and (string.find(objName, "plot") or string.find(objName, "base") or string.find(objName, "tycoon") or string.find(objName, "island") or string.find(objName, "house")) then
                local cf = getCFrameFromInstance(obj)
                if cf then
                    lastKnownPlotCF = cf
                    return cf
                end
            end
        end
    end

    -- 3. Check RespawnLocation
    if localPlayer.RespawnLocation and localPlayer.RespawnLocation:IsA("BasePart") then
        local cf = localPlayer.RespawnLocation.CFrame + Vector3.new(0, 3.5, 0)
        lastKnownPlotCF = cf
        return cf
    end

    if lastKnownPlotCF then
        return lastKnownPlotCF
    end

    local hrp = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
    if hrp then
        return hrp.CFrame
    end

    return nil
end

local function isEggInWild(eggObj, eggPart)
    -- 1. Ignore anything inside a player character
    if Players:GetPlayerFromCharacter(eggObj) or eggObj:FindFirstAncestorOfClass("Player") then
        return false
    end

    -- 2. Explicitly ignore Track Egg NPC, egg tracker, merchants, or quest/vendor models
    local lowerName = string.lower(eggObj.Name)
    if string.find(lowerName, "track") or string.find(lowerName, "npc") or string.find(lowerName, "shop") or string.find(lowerName, "vendor") or string.find(lowerName, "merchant") or string.find(lowerName, "guide") or string.find(lowerName, "quest") then
        return false
    end
    if eggPart then
        local pName = string.lower(eggPart.Name)
        if string.find(pName, "track") or string.find(pName, "npc") then
            return false
        end
    end
    -- Ignore models with humanoid / dialogue / animation controllers that represent NPCs
    if eggObj:IsA("Model") and (eggObj:FindFirstChildOfClass("Humanoid") or eggObj:FindFirstChild("Dialogue") or eggObj:FindFirstChild("NpcTag") or eggObj:FindFirstChild("NPC")) then
        return false
    end

    -- 3. Check all ancestors for plot, base, tycoon, NPC, or ownership keywords
    local curr = eggObj
    while curr and curr ~= workspace do
        local n = string.lower(curr.Name)
        if string.find(n, "plot") or string.find(n, "base") or string.find(n, "tycoon") or string.find(n, "house") or string.find(n, "island") or string.find(n, "npc") or string.find(n, "track") then
            return false
        end
        for _, attr in ipairs({"Owner", "Player", "UserId", "OwnerName", "PlayerName"}) do
            if curr:GetAttribute(attr) ~= nil then
                return false
            end
        end
        local ownerVal = curr:FindFirstChild("Owner") or curr:FindFirstChild("OwnerName") or curr:FindFirstChild("Player")
        if ownerVal and (ownerVal:IsA("StringValue") or ownerVal:IsA("ObjectValue") or ownerVal:IsA("NumberValue")) then
            return false
        end
        curr = curr.Parent
    end

    -- 4. Check distance from known plot structures in workspace
    local eggPos = eggPart.Position
    local plotContainers = {"Plots", "Bases", "Islands", "Tycoons", "PlayerPlots", "Houses", "Farms"}
    for _, cName in ipairs(plotContainers) do
        local container = workspace:FindFirstChild(cName)
        if container then
            for _, plot in ipairs(container:GetChildren()) do
                local plotPos = nil
                if plot:IsA("Model") then
                    plotPos = (plot.PrimaryPart and plot.PrimaryPart.Position) or plot:GetPivot().Position
                elseif plot:IsA("BasePart") then
                    plotPos = plot.Position
                end
                if plotPos and (eggPos - plotPos).Magnitude < 65 then
                    return false
                end
            end
        end
    end

    return true
end

