    if enabled then
        if not undergroundNoclipConn then
            undergroundNoclipConn = RunService.Stepped:Connect(function()
                pcall(function()
                    local char = localPlayer.Character
                    if char then
                        for _, p in ipairs(char:GetDescendants()) do
                            if p:IsA("BasePart") then
                                p.CanCollide = false
                            end
                        end
                    end
                end)
            end)
        end
    else
        if undergroundNoclipConn then
            undergroundNoclipConn:Disconnect()
            undergroundNoclipConn = nil
        end
    end
end

-- Unified Egg Steal & Grab Logic (Teleport directly to egg, auto-pickup, drop 1000 ft underground, return to base, restore walking)
local function executeEggSteal(targetEggObj, targetEggPart, targetEggName, targetRarity)
    local char = localPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 or not targetEggPart or not targetEggPart:IsDescendantOf(workspace) then
        return false
    end

    -- 1. Void and safety setup
    pcall(function() workspace.FallenPartsDestroyHeight = -50000 end)

    -- Remember base position before departure
    local initialPlotCF = getPlayerPlotCFrame() or lastKnownPlotCF or hrp.CFrame

    -- Remove any existing hold velocity before moving
    local oldBv = hrp:FindFirstChild("UndergroundHoldBV")
    if oldBv then oldBv:Destroy() end

    local eggPos = targetEggPart.Position

    -- 2. Teleport directly onto the egg
    hrp.CFrame = targetEggPart.CFrame
    pcall(function()
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end)

    -- Record initial inventory/character state to detect when egg is collected
    local initialCharChildren = {}
    for _, c in ipairs(char:GetChildren()) do initialCharChildren[c] = true end
    local backpack = localPlayer:FindFirstChild("Backpack")
    local initialBpChildren = {}
    if backpack then
        for _, c in ipairs(backpack:GetChildren()) do initialBpChildren[c] = true end
    end

    -- Stay directly on the egg and trigger all pickup mechanisms
    local eggPickedUp = false
    local pickupStart = tick()
    local maxPickupWait = 2.5

    while (tick() - pickupStart < maxPickupWait) do
        char = localPlayer.Character
        hrp = char and char:FindFirstChild("HumanoidRootPart")
        hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum or hum.Health <= 0 then break end

        -- Check if egg was picked up (despawned from workspace or moved to player)
        if (not targetEggPart:IsDescendantOf(workspace)) or (not targetEggObj:IsDescendantOf(workspace)) or targetEggPart.Parent == nil or targetEggObj.Parent == nil then
            eggPickedUp = true
            break
        end
        if targetEggObj:IsDescendantOf(char) or targetEggPart:IsDescendantOf(char) then
            eggPickedUp = true
            break
        end
        if backpack and (targetEggObj:IsDescendantOf(backpack) or targetEggPart:IsDescendantOf(backpack)) then
            eggPickedUp = true
            break
        end

        -- Check if any new tool or egg model was added to character or backpack
        for _, c in ipairs(char:GetChildren()) do
            if not initialCharChildren[c] and (c:IsA("Tool") or string.find(string.lower(c.Name), "egg")) then
                eggPickedUp = true
                break
            end
        end
        if backpack and not eggPickedUp then
            for _, c in ipairs(backpack:GetChildren()) do
                if not initialBpChildren[c] and (c:IsA("Tool") or string.find(string.lower(c.Name), "egg")) then
                    eggPickedUp = true
                    break
                end
            end
        end
        if eggPickedUp then break end

        -- Keep character locked directly on the egg
        hrp.CFrame = targetEggPart.CFrame
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)

        -- Trigger touch collection across all egg parts and character root
        pcall(function()
            for _, p in ipairs(targetEggObj:GetDescendants()) do
                if p:IsA("BasePart") then
                    firetouchinterest(hrp, p, 0)
                    task.wait()
                    firetouchinterest(hrp, p, 1)
                end
            end
            if targetEggPart:IsA("BasePart") then
                firetouchinterest(hrp, targetEggPart, 0)
                task.wait()
                firetouchinterest(hrp, targetEggPart, 1)
            end
        end)

        -- Trigger proximity prompts (instant hold duration, ignore line of sight)
        for _, prompt in ipairs(targetEggObj:GetDescendants()) do
            if prompt:IsA("ProximityPrompt") then
                pcall(function()
                    prompt.HoldDuration = 0
                    prompt.RequiresLineOfSight = false
                    prompt.MaxActivationDistance = 9999
                    fireproximityprompt(prompt)
                end)
            end
        end

        -- Trigger ClickDetectors if present
        for _, cd in ipairs(targetEggObj:GetDescendants()) do
            if cd:IsA("ClickDetector") then
                pcall(function()
                    cd.MaxActivationDistance = 9999
                    fireclickdetector(cd)
                end)
            end
        end

        -- Fire steal / egg pickup remotes in ReplicatedStorage
        pcall(function()
            local rep = game:GetService("ReplicatedStorage")
            for _, rem in ipairs(rep:GetDescendants()) do
                if rem:IsA("RemoteEvent") or rem:IsA("RemoteFunction") then
                    local n = string.lower(rem.Name)
                    if string.find(n, "steal") or string.find(n, "egg") or string.find(n, "hatch") or string.find(n, "claim") or string.find(n, "buy") or string.find(n, "click") or string.find(n, "tap") or string.find(n, "pickup") or string.find(n, "grab") or string.find(n, "collect") then
                        if rem:IsA("RemoteEvent") then
                            pcall(function() rem:FireServer(targetEggObj) end)
                            pcall(function() rem:FireServer(targetEggPart) end)
                            pcall(function() rem:FireServer(targetEggName or "Egg", targetRarity or "Common") end)
                            pcall(function() rem:FireServer("Claim", targetEggObj) end)
                            pcall(function() rem:FireServer("Grab", targetEggObj) end)
                        elseif rem:IsA("RemoteFunction") then
                            task.spawn(function()
                                pcall(function() rem:InvokeServer(targetEggObj) end)
                                pcall(function() rem:InvokeServer(targetEggName or "Egg", targetRarity or "Common") end)
                            end)
                        end
                    end
                end
            end
        end)

        task.wait(0.1)
    end

    -- Mark this egg as processed so it won't be immediately retargeted
    processedEggs[targetEggObj] = tick() + 6
    processedEggs[targetEggPart] = tick() + 6

    task.wait(0.2)

    -- 3. Teleport 1000 feet/studs below the egg AFTER picking it up
    char = localPlayer.Character
    hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then
        setUndergroundNoclip(true)
        pcall(function() workspace.FallenPartsDestroyHeight = -50000 end)
        local underPos = Vector3.new(eggPos.X, eggPos.Y - 1000, eggPos.Z)
        hrp.CFrame = CFrame.new(underPos)
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)

        -- Stabilize underground so player doesn't fall into the void
        local holdBv = hrp:FindFirstChild("UndergroundHoldBV")
        if not holdBv then
            holdBv = Instance.new("BodyVelocity")
            holdBv.Name = "UndergroundHoldBV"
            holdBv.MaxForce = Vector3.new(1e6, 1e6, 1e6)
            holdBv.Velocity = Vector3.zero
            holdBv.Parent = hrp
        end

        task.wait(0.6)
    end

    -- 4. Teleport back to player's base / plot
    local baseCF = getPlayerPlotCFrame() or initialPlotCF or lastKnownPlotCF
    char = localPlayer.Character
    hrp = char and char:FindFirstChild("HumanoidRootPart")
    hum = char and char:FindFirstChildOfClass("Humanoid")
    if hrp and baseCF then
        hrp.CFrame = baseCF + Vector3.new(0, 3.5, 0)
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    -- 5. Restore full walkability & physics at base
    pcall(function()
        -- Remove underground velocity hold
        if hrp then
            local bv = hrp:FindFirstChild("UndergroundHoldBV")
            if bv then bv:Destroy() end
            for _, m in ipairs(hrp:GetChildren()) do
                if m:IsA("BodyVelocity") or m:IsA("BodyPosition") or m:IsA("BodyGyro") then
                    if m.Name == "UndergroundHoldBV" then m:Destroy() end
                end
            end
        end

        -- Disable noclip so normal collision resumes
        setUndergroundNoclip(false)

        -- Restore part collisions on character
        if char then
            for _, p in ipairs(char:GetDescendants()) do
                if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" then
                    p.CanCollide = true
                end
            end
        end

        -- Restore humanoid state and movement
        if hum then
            hum.PlatformStand = false
            hum.Sit = false
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            task.wait(0.05)
            hum:ChangeState(Enum.HumanoidStateType.Running)
            hum.WalkSpeed = currentWalkSpeed or 16
            hum.JumpPower = currentJumpPower or 50
        end

        if hrp then
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
    end)

    return true
end

addToggle(farmContainer, "Steal Selected egg", false, function(enabled)
    autoSteal = enabled
    if not enabled then
        pcall(function()
            setUndergroundNoclip(false)
            local char = localPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                local bv = hrp:FindFirstChild("UndergroundHoldBV")
                if bv then bv:Destroy() end
            end
        end)
        return
    end

    task.spawn(function()
        while autoSteal do
            local char = localPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")

            if hrp and hum and hum.Health > 0 then
                local bestEggCandidate = nil
                local bestEggScore = -1
                local bestRarityScore = -1

                for _, obj in ipairs(workspace:GetDescendants()) do
                    if not autoSteal then break end
                    if (obj:IsA("Model") or obj:IsA("BasePart")) and not Players:GetPlayerFromCharacter(obj) and not obj:FindFirstAncestorOfClass("Player") then
                        if not processedEggs[obj] or tick() > processedEggs[obj] then
                            local eggDisplayName, rarity = getEggInfo(obj)
                            if eggDisplayName and rarity then
                                if isEggMatch(eggDisplayName) and isRarityMatch(rarity) then
                                    local part = (obj:IsA("BasePart") and obj) or obj:FindFirstChildWhichIsA("BasePart") or obj.PrimaryPart
                                    if part and (not processedEggs[part] or tick() > processedEggs[part]) and isEggInWild(obj, part) then
                                        local eScore, rScore = getEggScore(eggDisplayName, rarity)
                                        local dist = (part.Position - hrp.Position).Magnitude
                                        if not bestEggCandidate
                                            or eScore > bestEggScore
                                            or (eScore == bestEggScore and rScore > bestRarityScore)
                                            or (eScore == bestEggScore and rScore == bestRarityScore and dist < bestEggCandidate.dist) then
                                            bestEggCandidate = {
                                                obj = obj,
                                                part = part,
                                                name = eggDisplayName,
                                                rarity = rarity,
                                                dist = dist
                                            }
                                            bestEggScore = eScore
                                            bestRarityScore = rScore
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                if bestEggCandidate and autoSteal then
                    executeEggSteal(bestEggCandidate.obj, bestEggCandidate.part, bestEggCandidate.name, bestEggCandidate.rarity)
                    task.wait(0.4)
                else
                    task.wait(0.8)
                end
            else
                task.wait(0.5)
            end
        end

        pcall(function()
            setUndergroundNoclip(false)
            local char = localPlayer.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                local bv = hrp:FindFirstChild("UndergroundHoldBV")
                if bv then bv:Destroy() end
            end
        end)
    end)
end)

