local function getEggKgAndLuck(eggObj, eggPart, eggName, rarity)
    local kg = nil
    local luck = nil

    -- 1. Scan attributes
    for _, attr in ipairs({"KG", "Kg", "kg", "Weight", "Size", "Mass"}) do
        local val = eggObj:GetAttribute(attr) or (eggPart and eggPart:GetAttribute(attr))
        if val then
            kg = tostring(val)
            if not string.find(string.lower(kg), "kg") then kg = kg .. " KG" end
            break
        end
    end

    for _, attr in ipairs({"Luck", "Multiplier", "Multi", "Boost", "Power"}) do
        local val = eggObj:GetAttribute(attr) or (eggPart and eggPart:GetAttribute(attr))
        if val then
            luck = tostring(val)
            if not string.find(luck, "x") then luck = luck .. "x" end
            break
        end
    end

    -- 2. Scan TextLabels/descendants in egg
    if not kg or not luck then
        for _, desc in ipairs(eggObj:GetDescendants()) do
            if desc:IsA("TextLabel") then
                local txt = desc.Text
                if not kg and string.find(string.lower(txt), "kg") then
                    kg = txt
                end
                if not luck and (string.find(string.lower(txt), "luck") or string.find(txt, "x")) then
                    luck = txt
                end
            end
        end
    end

    -- 3. Calculate reasonable fallbacks based on part mass/size and luck table
    if not kg then
        if eggPart and eggPart:IsA("BasePart") then
            local mass = math.floor(eggPart.Size.X * eggPart.Size.Y * eggPart.Size.Z * 2.5 + 0.5)
            kg = tostring(math.clamp(mass, 1, 9999)) .. " KG"
        else
            kg = "10 KG"
        end
    end

    if not luck then
        luck = eggLuckMap[eggName] or (rarity == "Mythic" and "200x") or (rarity == "Legendary" and "50x") or (rarity == "Epic" and "10x") or (rarity == "Rare" and "3x") or "1x"
    end

    return kg, luck
end

