local function parseKgValue(kgStr)
    if not kgStr then return 0 end
    local lower = string.lower(tostring(kgStr))
    local clean = string.gsub(lower, ",", "")
    local num = tonumber(string.match(clean, "%d+%.?%d*")) or 0
    if string.find(clean, "b") then
        num = num * 1000000000
    elseif string.find(clean, "m") then
        num = num * 1000000
    elseif string.match(clean, "%d+%.?%d*%s*k[^g]") or string.match(clean, "%d+%.?%d*k$") then
        num = num * 1000
    end
    return num
end

