-- Drag logic for SpawnedEggsFrame
local sDragging = false
local sDragStart = nil
local sStartPos = nil

SpawnedTopBar.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        sDragging = true
        sDragStart = input.Position
        sStartPos = SpawnedEggsFrame.Position
        local conn
        conn = input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                sDragging = false
                if conn then conn:Disconnect() end
            end
        end)
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if sDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
        local delta = input.Position - sDragStart
        SpawnedEggsFrame.Position = UDim2.new(
            sStartPos.X.Scale,
            sStartPos.X.Offset + delta.X,
            sStartPos.Y.Scale,
            sStartPos.Y.Offset + delta.Y
        )
    end
end)



-- Refresh Spawned Eggs List
refreshSpawnedEggs = function()
    if SortDropdownFrame then SortDropdownFrame.Visible = false end

    for _, item in ipairs(SpawnedList:GetChildren()) do
        if item:IsA("Frame") then item:Destroy() end
    end

    local char = localPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local myPos = hrp and hrp.Position or Vector3.zero

    local foundEggs = {}

    for _, obj in ipairs(workspace:GetDescendants()) do
        if (obj:IsA("Model") or obj:IsA("BasePart")) and not Players:GetPlayerFromCharacter(obj) and not obj:FindFirstAncestorOfClass("Player") then
            local eggDisplayName, rarity = getEggInfo(obj)
            if eggDisplayName and rarity then
                local part = (obj:IsA("BasePart") and obj) or obj:FindFirstChildWhichIsA("BasePart") or obj.PrimaryPart
                if part and isEggInWild(obj, part) then
                    local kg, luck = getEggKgAndLuck(obj, part, eggDisplayName, rarity)
                    local dist = math.floor((part.Position - myPos).Magnitude + 0.5)
                    local kgVal = parseKgValue(kg)
                    table.insert(foundEggs, {
                        obj = obj,
                        part = part,
                        name = eggDisplayName,
                        rarity = rarity,
                        kg = kg,
                        kgVal = kgVal,
                        luck = luck,
                        dist = dist
                    })
                end
            end
        end
    end

    -- Sort eggs according to the active sort mode
    if spawnedSortMode == "Highest KG" then
        table.sort(foundEggs, function(a, b)
            if a.kgVal ~= b.kgVal then
                return a.kgVal > b.kgVal
            else
                local eRankA, rRankA = getEggScore(a.name, a.rarity)
                local eRankB, rRankB = getEggScore(b.name, b.rarity)
                if eRankA ~= eRankB then
                    return eRankA > eRankB
                elseif rRankA ~= rRankB then
                    return rRankA > rRankB
                else
                    return a.dist < b.dist
                end
            end
        end)
    elseif spawnedSortMode == "Closest Distance" then
        table.sort(foundEggs, function(a, b)
            return a.dist < b.dist
        end)
    else -- "Highest Rarity" (Default)
        table.sort(foundEggs, function(a, b)
            local eRankA, rRankA = getEggScore(a.name, a.rarity)
            local eRankB, rRankB = getEggScore(b.name, b.rarity)
            if eRankA ~= eRankB then
                return eRankA > eRankB
            elseif rRankA ~= rRankB then
                return rRankA > rRankB
            else
                return a.dist < b.dist
            end
        end)
    end

    SpawnedSummary.Text = string.format("Found %d wild egg(s) spawned in:", #foundEggs)

    if #foundEggs == 0 then
        local emptyLabel = Instance.new("TextLabel")
        emptyLabel.Parent = SpawnedList
        emptyLabel.BackgroundTransparency = 1.000
        emptyLabel.Size = UDim2.new(1, 0, 0, 40)
        emptyLabel.Font = Enum.Font.Gotham
        emptyLabel.Text = "No wild eggs found in workspace right now."
        emptyLabel.TextColor3 = Color3.fromRGB(140, 145, 155)
        emptyLabel.TextSize = 11.000
        return
    end

    for i, eggData in ipairs(foundEggs) do
        local rColor = rarityColors[eggData.rarity] or Color3.fromRGB(255, 255, 255)

        local row = Instance.new("Frame")
        row.Name = "EggRow_" .. tostring(i)
        row.Parent = SpawnedList
        row.BackgroundColor3 = Color3.fromRGB(24, 26, 33)
        row.BorderSizePixel = 0
        row.Size = UDim2.new(1, 0, 0, 48)

        local rowCorner = Instance.new("UICorner")
        rowCorner.CornerRadius = UDim.new(0, 6)
        rowCorner.Parent = row

        local rowStroke = Instance.new("UIStroke")
        rowStroke.Color = Color3.fromRGB(42, 46, 56)
        rowStroke.Thickness = 1
        rowStroke.Parent = row

        -- Left color bar indicating rarity
        local rBar = Instance.new("Frame")
        rBar.Parent = row
        rBar.BackgroundColor3 = rColor
        rBar.BorderSizePixel = 0
        rBar.Position = UDim2.new(0, 0, 0, 0)
        rBar.Size = UDim2.new(0, 4, 1, 0)

        local rBarCorner = Instance.new("UICorner")
        rBarCorner.CornerRadius = UDim.new(0, 4)
        rBarCorner.Parent = rBar

        -- Title: Egg Name & Rarity
        local titleLbl = Instance.new("TextLabel")
        titleLbl.Parent = row
        titleLbl.BackgroundTransparency = 1.000
        titleLbl.Position = UDim2.new(0, 10, 0, 4)
        titleLbl.Size = UDim2.new(1, -95, 0, 18)
        titleLbl.Font = Enum.Font.GothamBold
        titleLbl.Text = eggData.name .. "  •  " .. eggData.rarity
        titleLbl.TextColor3 = Color3.fromRGB(245, 245, 250)
        titleLbl.TextSize = 11.000
        titleLbl.TextXAlignment = Enum.TextXAlignment.Left

        -- Subtitle: KG, Luck, and Distance
        local infoLbl = Instance.new("TextLabel")
        infoLbl.Parent = row
        infoLbl.BackgroundTransparency = 1.000
        infoLbl.Position = UDim2.new(0, 10, 0, 24)
        infoLbl.Size = UDim2.new(1, -95, 0, 18)
        infoLbl.Font = Enum.Font.Gotham
        infoLbl.Text = string.format("⚖ %s   |   ✨ %s Luck   |   📍 %d studs", eggData.kg, eggData.luck, eggData.dist)
        infoLbl.TextColor3 = Color3.fromRGB(160, 170, 185)
        infoLbl.TextSize = 10.000
        infoLbl.TextXAlignment = Enum.TextXAlignment.Left

        -- Grab Button
        local grabBtn = Instance.new("TextButton")
        grabBtn.Parent = row
        grabBtn.BackgroundColor3 = Color3.fromRGB(36, 110, 72)
        grabBtn.BorderSizePixel = 0
        grabBtn.Position = UDim2.new(1, -78, 0.5, -13)
        grabBtn.Size = UDim2.new(0, 70, 0, 26)
        grabBtn.Font = Enum.Font.GothamBold
        grabBtn.Text = "GRAB"
        grabBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
        grabBtn.TextSize = 10.000

        local grabCorner = Instance.new("UICorner")
        grabCorner.CornerRadius = UDim.new(0, 5)
        grabCorner.Parent = grabBtn

        local grabStroke = Instance.new("UIStroke")
        grabStroke.Color = Color3.fromRGB(50, 160, 100)
        grabStroke.Thickness = 1
        grabStroke.Parent = grabBtn

        grabBtn.MouseEnter:Connect(function()
            grabBtn.BackgroundColor3 = Color3.fromRGB(45, 135, 88)
        end)
        grabBtn.MouseLeave:Connect(function()
            grabBtn.BackgroundColor3 = Color3.fromRGB(36, 110, 72)
        end)

        grabBtn.MouseButton1Click:Connect(function()
            if clickSound then clickSound:Play() end
            grabBtn.Text = "GRABBING..."
            grabBtn.BackgroundColor3 = Color3.fromRGB(180, 110, 30)
            task.spawn(function()
                executeEggSteal(eggData.obj, eggData.part, eggData.name, eggData.rarity)
                task.wait(0.5)
                pcall(refreshSpawnedEggs)
            end)
        end)
    end
end

SpawnedRefreshBtn.MouseButton1Click:Connect(function()
    if clickSound then clickSound:Play() end
    refreshSpawnedEggs()
end)

