-- Pet Mods Card
local petCard, petContainer = createCard(mainPage, "PET MANAGEMENT & MULTIPLIERS", 75)

local function placeBestPetsFromInventory()
    local placedCount = 0

    -- 1. Scan PlayerGui for the in-game "Place Best" / "Place All" button
    local pGui = localPlayer:FindFirstChild("PlayerGui")
    if pGui then
        for _, desc in ipairs(pGui:GetDescendants()) do
            if desc:IsA("GuiButton") then
                local bName = string.lower(desc.Name)
                local bText = (desc:IsA("TextButton") and string.lower(desc.Text)) or ""
                for _, child in ipairs(desc:GetChildren()) do
                    if child:IsA("TextLabel") then
                        bText = bText .. " " .. string.lower(child.Text)
                    end
                end

                if string.find(bText, "place best") or string.find(bText, "placebest")
                    or string.find(bName, "placebest") or string.find(bName, "place_best")
                    or string.find(bText, "place all") or string.find(bName, "placeall")
                    or (string.find(bText, "best") and string.find(bText, "place"))
                    or (string.find(bText, "equip best") or string.find(bName, "equipbest")) then
                    
                    pcall(function()
                        if firesignal then
                            firesignal(desc.MouseButton1Click)
                            firesignal(desc.Activated)
                            firesignal(desc.MouseButton1Down)
                            firesignal(desc.MouseButton1Up)
                        end
                    end)
                    pcall(function()
                        if getconnections then
                            for _, conn in ipairs(getconnections(desc.MouseButton1Click)) do conn:Fire() end
                            for _, conn in ipairs(getconnections(desc.Activated)) do conn:Fire() end
                        end
                    end)
                    placedCount = placedCount + 1
                end
            end
        end
    end

    -- 2. Scan Player's Plot / Base in Workspace for "Place Best" stands, SurfaceGuis, BillboardGuis & ProximityPrompts
    local plotCF = getPlayerPlotCFrame() or lastKnownPlotCF
    if plotCF then
        for _, part in ipairs(workspace:GetDescendants()) do
            if part:IsA("BasePart") and (part.Position - plotCF.Position).Magnitude < 90 then
                for _, gui in ipairs(part:GetChildren()) do
                    if gui:IsA("SurfaceGui") or gui:IsA("BillboardGui") then
                        for _, btn in ipairs(gui:GetDescendants()) do
                            if btn:IsA("GuiButton") then
                                local bTxt = (btn:IsA("TextButton") and string.lower(btn.Text)) or ""
                                local bName = string.lower(btn.Name)
                                for _, child in ipairs(btn:GetChildren()) do
                                    if child:IsA("TextLabel") then
                                        bTxt = bTxt .. " " .. string.lower(child.Text)
                                    end
                                end
                                if string.find(bTxt, "place best") or string.find(bTxt, "placebest")
                                    or string.find(bName, "placebest") or string.find(bName, "place_best")
                                    or string.find(bTxt, "place all") then
                                    pcall(function()
                                        if firesignal then
                                            firesignal(btn.MouseButton1Click)
                                            firesignal(btn.Activated)
                                        end
                                    end)
                                    pcall(function()
                                        if getconnections then
                                            for _, conn in ipairs(getconnections(btn.MouseButton1Click)) do conn:Fire() end
                                        end
                                    end)
                                    placedCount = placedCount + 1
                                end
                            end
                        end
                    end
                end

                for _, prompt in ipairs(part:GetChildren()) do
                    if prompt:IsA("ProximityPrompt") then
                        local actText = string.lower(prompt.ActionText or "")
                        local objText = string.lower(prompt.ObjectText or "")
                        if string.find(actText, "place best") or string.find(actText, "place") or string.find(objText, "place best") then
                            pcall(function()
                                prompt.HoldDuration = 0
                                fireproximityprompt(prompt)
                            end)
                            placedCount = placedCount + 1
                        end
                    end
                end
            end
        end
    end

    -- 3. Scan Inventory for the highest profitable pet slots & equip/place them
    if pGui then
        local petCandidates = {}
        for _, frame in ipairs(pGui:GetDescendants()) do
            if frame:IsA("Frame") or frame:IsA("ImageLabel") or frame:IsA("ImageButton") then
                local fName = string.lower(frame.Name)
                if string.find(fName, "pet") or string.find(fName, "slot") or string.find(fName, "item") or string.find(fName, "inv") then
                    local profit = 0
                    local targetBtn = nil
                    for _, d in ipairs(frame:GetDescendants()) do
                        if d:IsA("TextLabel") then
                            local t = string.lower(d.Text)
                            local mult = 1
                            if string.find(t, "b") then mult = 1e9
                            elseif string.find(t, "m") then mult = 1e6
                            elseif string.find(t, "k") then mult = 1e3 end
                            local num = tonumber(string.match(t, "%d+%.?%d*"))
                            if num then
                                local score = num * mult
                                if score > profit then profit = score end
                            end
                        elseif d:IsA("GuiButton") and (string.find(string.lower(d.Name), "equip") or string.find(string.lower(d.Name), "place") or string.find(string.lower(d:IsA("TextButton") and d.Text or ""), "place") or string.find(string.lower(d:IsA("TextButton") and d.Text or ""), "equip")) then
                            targetBtn = d
                        end
                    end
                    if targetBtn then
                        table.insert(petCandidates, { btn = targetBtn, profit = profit })
                    end
                end
            end
        end

        if #petCandidates > 0 then
            table.sort(petCandidates, function(a, b) return a.profit > b.profit end)
            for i = 1, math.min(#petCandidates, 12) do
                pcall(function()
                    if firesignal then
                        firesignal(petCandidates[i].btn.MouseButton1Click)
                        firesignal(petCandidates[i].btn.Activated)
                    end
                end)
                pcall(function()
                    if getconnections then
                        for _, conn in ipairs(getconnections(petCandidates[i].btn.MouseButton1Click)) do conn:Fire() end
                    end
                end)
            end
        end
    end

    -- 4. Fire all game ReplicatedStorage remotes related to Place Best / Equip Best
    pcall(function()
        local rep = game:GetService("ReplicatedStorage")
        for _, rem in ipairs(rep:GetDescendants()) do
            if rem:IsA("RemoteEvent") or rem:IsA("RemoteFunction") then
                local n = string.lower(rem.Name)
                if string.find(n, "placebest") or string.find(n, "place_best")
                    or string.find(n, "equipbest") or string.find(n, "equip_best")
                    or string.find(n, "placeall") or string.find(n, "place_all")
                    or string.find(n, "bestpet") or string.find(n, "autoplace")
                    or string.find(n, "placepets") or string.find(n, "bestpets") then
                    if rem:IsA("RemoteEvent") then
                        pcall(function() rem:FireServer() end)
                        pcall(function() rem:FireServer(true) end)
                        pcall(function() rem:FireServer("Best") end)
                    elseif rem:IsA("RemoteFunction") then
                        task.spawn(function()
                            pcall(function() rem:InvokeServer() end)
                            pcall(function() rem:InvokeServer(true) end)
                            pcall(function() rem:InvokeServer("Best") end)
                        end)
                    end
                    placedCount = placedCount + 1
                end
            end
        end
    end)

    return placedCount
end

addButton(petContainer, "Equip Best Available Pets", "PLACE BEST", function()
    task.spawn(function()
        placeBestPetsFromInventory()
    end)
end)

