local visualPage = pages.Visual

-- Egg ESP & Rarity Highlights
local eggEspCard, eggEspContainer = createCard(visualPage, "EGG ESP & HIGHLIGHTS", 120)

local eggEsp = false
local eggEspRarities = { ["All"] = true }
local eggEspObjects = {}

local function isEspRarityMatch(rarity)
    if not rarity then return false end
    if eggEspRarities["All"] then return true end
    for selRarity, sel in pairs(eggEspRarities) do
        if sel and string.lower(selRarity) == string.lower(rarity) then
            return true
        end
    end
    return false
end

local function clearEggEsp()
    for _, item in pairs(eggEspObjects) do
        pcall(function()
            if item.hl then item.hl:Destroy() end
            if item.bb then item.bb:Destroy() end
        end)
    end
    table.clear(eggEspObjects)
end

local function updateEggEsp()
    if not eggEsp then return end
    for _, obj in ipairs(workspace:GetDescendants()) do
        if not eggEsp then break end
        if (obj:IsA("Model") or obj:IsA("BasePart")) and not eggEspObjects[obj] then
            if not Players:GetPlayerFromCharacter(obj) and not obj:FindFirstAncestorOfClass("Player") then
                local eggDisplayName, rarity = getEggInfo(obj)
                if eggDisplayName and rarity then
                    if isEspRarityMatch(rarity) then
                        local color = rarityColors[rarity] or Color3.fromRGB(255, 255, 255)

                        local hl = Instance.new("Highlight")
                        hl.Name = "EggESP_HL"
                        hl.Adornee = obj
                        hl.FillColor = color
                        hl.FillTransparency = 0.55
                        hl.OutlineColor = Color3.fromRGB(255, 255, 255)
                        hl.OutlineTransparency = 0.15
                        hl.Parent = StandaloneGui

                        local bb = nil
                        local adorneePart = (obj:IsA("BasePart") and obj) or obj:FindFirstChildWhichIsA("BasePart") or obj.PrimaryPart
                        if adorneePart then
                            bb = Instance.new("BillboardGui")
                            bb.Name = "EggESP_BB"
                            bb.Adornee = adorneePart
                            bb.Size = UDim2.new(0, 180, 0, 40)
                            bb.StudsOffset = Vector3.new(0, 3.5, 0)
                            bb.AlwaysOnTop = true
                            bb.Parent = StandaloneGui

                            local nameLbl = Instance.new("TextLabel")
                            nameLbl.Parent = bb
                            nameLbl.BackgroundTransparency = 1.000
                            nameLbl.Position = UDim2.new(0, 0, 0, 0)
                            nameLbl.Size = UDim2.new(1, 0, 0, 20)
                            nameLbl.Font = Enum.Font.GothamBold
                            nameLbl.Text = eggDisplayName
                            nameLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
                            nameLbl.TextSize = 13.000
                            nameLbl.TextStrokeColor3 = Color3.fromRGB(15, 15, 18)
                            nameLbl.TextStrokeTransparency = 0.1

                            local rarityLbl = Instance.new("TextLabel")
                            rarityLbl.Parent = bb
                            rarityLbl.BackgroundTransparency = 1.000
                            rarityLbl.Position = UDim2.new(0, 0, 0, 20)
                            rarityLbl.Size = UDim2.new(1, 0, 0, 18)
                            rarityLbl.Font = Enum.Font.GothamBold
                            rarityLbl.Text = "[ " .. string.upper(rarity) .. " ]"
                            rarityLbl.TextColor3 = color
                            rarityLbl.TextSize = 11.000
                            rarityLbl.TextStrokeColor3 = Color3.fromRGB(15, 15, 18)
                            rarityLbl.TextStrokeTransparency = 0.1
                        end

                        eggEspObjects[obj] = { hl = hl, bb = bb }
                    end
                end
            end
        end
    end
end

addToggle(eggEspContainer, "Egg ESP (Highlight Eggs)", false, function(enabled)
    eggEsp = enabled
    if not enabled then
        clearEggEsp()
    else
        task.spawn(function()
            while eggEsp do
                pcall(updateEggEsp)
                task.wait(1.5)
            end
        end)
    end
end)

addDropdown(eggEspContainer, "Filter by Rarity", rarityList, { ["All"] = true }, function(choices)
    eggEspRarities = choices
    clearEggEsp()
    if eggEsp then
        pcall(updateEggEsp)
    end
end, true)

local espCard, espContainer = createCard(visualPage, "PLAYER ESP & ENVIRONMENT", 175)

-- Player ESP
local playerEsp = false
local espObjects = {}
local function clearEsp()
    for _, v in pairs(espObjects) do
        pcall(function() v:Destroy() end)
    end
    table.clear(espObjects)
end

addToggle(espContainer, "Player ESP (Chams / Highlights)", false, function(enabled)
    playerEsp = enabled
    if not enabled then
        clearEsp()
    else
        task.spawn(function()
            while playerEsp do
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr ~= localPlayer and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                        if not espObjects[plr] or not espObjects[plr].Parent then
                            pcall(function()
                                local hl = Instance.new("Highlight")
                                hl.Name = "InfinityESP"
                                hl.Adornee = plr.Character
                                hl.FillColor = Color3.fromRGB(0, 160, 240)
                                hl.FillTransparency = 0.5
                                hl.OutlineColor = Color3.fromRGB(255, 255, 255)
                                hl.OutlineTransparency = 0.2
                                hl.Parent = MainFrame
                                espObjects[plr] = hl
                            end)
                        end
                    end
                end
                task.wait(1.5)
            end
        end)
    end
end)

-- Fullbright
local fullbright = false
local oldLighting = {
    Brightness = Lighting.Brightness,
    ClockTime = Lighting.ClockTime,
    FogEnd = Lighting.FogEnd,
    GlobalShadows = Lighting.GlobalShadows
}
addToggle(espContainer, "Fullbright (Maximum Vision)", false, function(enabled)
    fullbright = enabled
    pcall(function()
        if enabled then
            Lighting.Brightness = 2
            Lighting.ClockTime = 14
            Lighting.FogEnd = 100000
            Lighting.GlobalShadows = false
        else
            Lighting.Brightness = oldLighting.Brightness
            Lighting.ClockTime = oldLighting.ClockTime
            Lighting.FogEnd = oldLighting.FogEnd
            Lighting.GlobalShadows = oldLighting.GlobalShadows
        end
    end)
end)

-- Camera FOV
local fovRow = Instance.new("Frame")
fovRow.Parent = espContainer
fovRow.BackgroundTransparency = 1.000
fovRow.Size = UDim2.new(1, 0, 0, 28)

local fovLabel = Instance.new("TextLabel")
fovLabel.Parent = fovRow
fovLabel.BackgroundTransparency = 1.000
fovLabel.Size = UDim2.new(0, 100, 1, 0)
fovLabel.Font = Enum.Font.Gotham
fovLabel.Text = "Camera FOV:"
fovLabel.TextColor3 = Color3.fromRGB(225, 228, 235)
fovLabel.TextSize = 11.000
fovLabel.TextXAlignment = Enum.TextXAlignment.Left

local fovOptions = {70, 90, 110}
local fovBtns = {}
for i, fov in ipairs(fovOptions) do
    local isDefault = (fov == 70)
    local btn = Instance.new("TextButton")
    btn.Parent = fovRow
    btn.BackgroundColor3 = isDefault and Color3.fromRGB(38, 56, 82) or Color3.fromRGB(30, 32, 38)
    btn.BorderSizePixel = 0
    btn.Position = UDim2.new(1, -190 + (i - 1) * 64, 0.5, -12)
    btn.Size = UDim2.new(0, 58, 0, 24)
    btn.Font = Enum.Font.GothamBold
    btn.Text = tostring(fov)
    btn.TextColor3 = isDefault and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(160, 165, 175)
    btn.TextSize = 11.000

    local btnCorner = Instance.new("UICorner")
    btnCorner.CornerRadius = UDim.new(0, 5)
    btnCorner.Parent = btn

    local stroke = Instance.new("UIStroke")
    stroke.Color = isDefault and Color3.fromRGB(65, 95, 140) or Color3.fromRGB(50, 54, 64)
    stroke.Thickness = 1
    stroke.Parent = btn

    btn.MouseButton1Click:Connect(function()
        if clickSound then clickSound:Play() end
        for _, b in ipairs(fovBtns) do
            b.btn.BackgroundColor3 = Color3.fromRGB(30, 32, 38)
            b.btn.TextColor3 = Color3.fromRGB(160, 165, 175)
            b.stroke.Color = Color3.fromRGB(50, 54, 64)
        end
        btn.BackgroundColor3 = Color3.fromRGB(38, 56, 82)
        btn.TextColor3 = Color3.fromRGB(255, 255, 255)
        stroke.Color = Color3.fromRGB(65, 95, 140)
        pcall(function()
            workspace.CurrentCamera.FieldOfView = fov
        end)
    end)
    table.insert(fovBtns, {btn = btn, stroke = stroke})
end

