local settingsPage = pages.Settings
local hubNavCard, hubNavContainer = createCard(settingsPage, "NAVIGATION & SERVER CONTROLS", 145)

-- Rejoin Server
addButton(hubNavContainer, "Rejoin Current Experience", "REJOIN", function()
    pcall(function()
        if #Players:GetPlayers() <= 1 then
            localPlayer:Kick("\n[Ride A Pet] Rejoining server...")
            task.wait(0.5)
            TeleportService:Teleport(game.PlaceId, localPlayer)
        else
            TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, localPlayer)
        end
    end)
end)

-- Server Hop
addButton(hubNavContainer, "Hop to Another Public Server", "HOP", function()
    task.spawn(function()
        local success, servers = pcall(function()
            local sfUrl = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100"
            return game:HttpGet(sfUrl)
        end)
        if success and servers then
            local parsed = HttpService:JSONDecode(servers)
            if parsed and parsed.data then
                for _, server in ipairs(parsed.data) do
                    if type(server) == "table" and server.id ~= game.JobId and server.playing < server.maxPlayers then
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, localPlayer)
                        return
                    end
                end
            end
        end
        TeleportService:Teleport(game.PlaceId, localPlayer)
    end)
end)

